import struct
import ipaddress

PCAPNG_SHB = 0x0A0D0D0A
PCAPNG_IDB = 0x00000001
PCAPNG_EPB = 0x00000006

def read_u32(b, off, endian):
    return struct.unpack(endian + "I", b[off:off+4])[0]

def parse_pcapng(fname):
    data = open(fname, "rb").read()
    off = 0
    endian = "<"  # default; will be set by SHB
    first = True
    while off + 12 <= len(data):
        block_type = struct.unpack("<I", data[off:off+4])[0]
        block_len_le = struct.unpack("<I", data[off+4:off+8])[0]
        if block_len_le < 12 or off + block_len_le > len(data):
            break
        body = data[off+8:off+block_len_le-4]
        if block_type == PCAPNG_SHB:
            # Byte-order magic at start of SHB body
            if len(body) >= 4:
                bom = struct.unpack("<I", body[:4])[0]
                if bom == 0x1A2B3C4D:
                    endian = "<"
                elif bom == 0x4D3C2B1A:
                    endian = ">"
                else:
                    endian = "<"
        yield block_type, body, endian
        off += block_len_le

def extract_server_payload(pcap_path, server_ip, server_port):
    server_ip_packed = ipaddress.IPv4Address(server_ip).packed
    buf = bytearray()
    for btype, body, endian in parse_pcapng(pcap_path):
        if btype != PCAPNG_EPB:
            continue
        if len(body) < 20:
            continue
        # EPB body: interface_id(4), ts_hi(4), ts_lo(4), cap_len(4), orig_len(4), pkt_data..., options...
        cap_len = read_u32(body, 12, endian)
        pkt_data = body[20:20+cap_len]
        if len(pkt_data) < 54:
            continue
        # Ethernet
        eth_type = struct.unpack("!H", pkt_data[12:14])[0]
        if eth_type != 0x0800:
            continue
        # IPv4
        iphdr = pkt_data[14:]
        ver_ihl = iphdr[0]
        if (ver_ihl >> 4) != 4:
            continue
        ihl = (ver_ihl & 0x0F) * 4
        proto = iphdr[9]
        if proto != 6:
            continue
        src_ip = iphdr[12:16]
        dst_ip = iphdr[16:20]
        # TCP
        tcphdr = iphdr[ihl:ihl+20]
        if len(tcphdr) < 20:
            continue
        src_port = struct.unpack("!H", tcphdr[0:2])[0]
        dst_port = struct.unpack("!H", tcphdr[2:4])[0]
        doff = ((tcphdr[12] >> 4) & 0x0F) * 4
        payload = iphdr[ihl+doff:]
        if not payload:
            continue
        # Filter: server -> client on specified port
        if src_ip == server_ip_packed and src_port == server_port:
            buf.extend(payload)
    return bytes(buf)

def extract_http_body(server_stream):
    # Find HTTP response and Content-Length
    hdr_start = server_stream.find(b"HTTP/1.")
    if hdr_start == -1:
        return None, None
    hdr_end = server_stream.find(b"\r\n\r\n", hdr_start)
    if hdr_end == -1:
        return None, None
    headers = server_stream[hdr_start:hdr_end].decode("latin1", errors="ignore")
    clen = None
    for line in headers.split("\r\n")[1:]:
        if line.lower().startswith("content-length:"):
            try:
                clen = int(line.split(":",1)[1].strip())
            except:
                pass
    body = server_stream[hdr_end+4:]
    if clen is None or len(body) < clen:
        return None, None
    return body[:clen], headers

def main():
    pcap = "capture.pcap"
    srv_ip = "10.10.10.21"
    srv_port = 8000
    stream = extract_server_payload(pcap, srv_ip, srv_port)
    body, headers = extract_http_body(stream)
    if body is None:
        print("Failed to extract HTTP body")
        return
    with open("aQ4caZ.exe", "wb") as f:
        f.write(body)
    print("Saved aQ4caZ.exe, size:", len(body))
    if headers:
        print("Headers:")
        for line in headers.split("\\r\\n"):
            print(line)

if __name__ == "__main__":
    main()
